1	//! Entry binary for the test13 harness.
2	//!
3	//! Includes the library modules directly via `#[path]` so that both
4	//! `cargo build --release` (via the `[[bin]]` target) and a plain
5	//! `rustc --edition=2021 test13.rs` invocation work from the project root.
6	
7	#[path = "src/pluralize.rs"]
8	mod pluralize;
9	#[path = "src/text.rs"]
10	mod text;
11	
12	use std::env;
13	
14	fn main() {
15	    let mut args = env::args();
16	    let _ = args.next(); // program name
17	    let word = match args.next() {
18	        Some(w) => w,
19	        None => return, // no argv[1]: print nothing, exit 0
20	    };
21	    // Extra args are ignored; argv[1] is treated literally.
22	
23	    let lines = [
24	        pluralize::pluralize(&word),
25	        pluralize::singularize(&format!("{word}s")),
26	        text::camelize(&format!("test_{word}")),
27	        text::underscore(&format!("Test{word}")),
28	        text::classify(&format!("{word}_table")),
29	        text::tableize(&format!("{word}Class")),
30	        text::humanize(&format!("{word}_id")),
31	        text::titleize(&word),
32	        text::dasherize(&word),
33	        text::parameterize(&format!("The {word} Test")),
34	        text::upcase(&word),
35	        text::downcase(&word),
36	        text::capitalize(&word),
37	    ];
38	
39	    let mut out = String::new();
40	    for line in &lines {
41	        out.push_str(line);
42	        out.push('\n');
43	    }
44	    print!("{out}");
45	}

1	//! Pluralization and singularization rules.
2	
3	/// Exact, case-sensitive uncountable words.
4	const UNCOUNTABLES: [&str; 10] = [
5	    "equipment",
6	    "information",
7	    "rice",
8	    "money",
9	    "species",
10	    "series",
11	    "fish",
12	    "sheep",
13	    "jeans",
14	    "police",
15	];
16	
17	fn is_uncountable(word: &str) -> bool {
18	    UNCOUNTABLES.iter().any(|u| *u == word)
19	}
20	
21	fn replace_suffix(word: &str, from: &str, to: &str) -> String {
22	    let mut s = String::with_capacity(word.len() - from.len() + to.len());
23	    s.push_str(&word[..word.len() - from.len()]);
24	    s.push_str(to);
25	    s
26	}
27	
28	fn strip_last(word: &str, n: usize) -> String {
29	    word[..word.len() - n].to_string()
30	}
31	
32	/// Append ASCII `s`, unless empty or an exact uncountable.
33	pub fn pluralize(word: &str) -> String {
34	    if word.is_empty() || is_uncountable(word) {
35	        return word.to_string();
36	    }
37	    let mut s = String::with_capacity(word.len() + 1);
38	    s.push_str(word);
39	    s.push('s');
40	    s
41	}
42	
43	/// Singularize via first matching case-sensitive lowercase suffix rule.
44	pub fn singularize(word: &str) -> String {
45	    if word.is_empty() || is_uncountable(word) {
46	        return word.to_string();
47	    }
48	    let ends = |suf: &str| word.ends_with(suf);
49	
50	    if ends("quizzes") {
51	        return replace_suffix(word, "quizzes", "quiz");
52	    }
53	    if ends("matrices") {
54	        return replace_suffix(word, "matrices", "matrix");
55	    }
56	    if ends("vertices") {
57	        return replace_suffix(word, "vertices", "vertex");
58	    }
59	    if ends("indices") {
60	        return replace_suffix(word, "indices", "index");
61	    }
62	    if ends("aliases") {
63	        return strip_last(word, 2);
64	    }
65	    if ends("statuses") {
66	        return strip_last(word, 2);
67	    }
68	    if ends("crises") {
69	        return replace_suffix(word, "es", "is");
70	    }
71	    if ends("axes") {
72	        return replace_suffix(word, "es", "is");
73	    }
74	    if ends("testes") {
75	        return replace_suffix(word, "es", "is");
76	    }
77	    if ends("oes") {
78	        return replace_suffix(word, "oes", "o");
79	    }
80	    if ends("buses") {
81	        return replace_suffix(word, "buses", "bus");
82	    }
83	    if ends("xes") || ends("ches") || ends("sses") || ends("shes") {
84	        return strip_last(word, 2);
85	    }
86	    if ends("ies") {
87	        // consonant/qu + ies -> consonant/qu + y
88	        if ends("quies") {
89	            return replace_suffix(word, "ies", "y");
90	        }
91	        let b = word.as_bytes();
92	        if b.len() >= 4 {
93	            let prev = b[b.len() - 4];
94	            if !matches!(prev, b'a' | b'e' | b'i' | b'o' | b'u' | b'y') {
95	                // any non-(lowercase-vowel) byte before "ies": ies -> y
96	                return replace_suffix(word, "ies", "y");
97	            }
98	        }
99	        // lowercase vowel + ies (or bare "ies"): only strip the final s
100	        return strip_last(word, 1);
101	    }
102	    if ends("ves") {
103	        let b = word.as_bytes();
104	        if b.len() >= 4 && b[b.len() - 4] != b'f' {
105	            return replace_suffix(word, "ves", "fe");
106	        }
107	        // "fves" and bare "ves" fall through to later rules
108	    }
109	    if ends("analyses") {
110	        // quirk: analyses -> analyasis
111	        return replace_suffix(word, "analyses", "analyasis");
112	    }
113	    for (from, to) in [
114	        ("bases", "basis"),
115	        ("diagnoses", "diagnosis"),
116	        ("parentheses", "parenthesis"),
117	        ("prognoses", "prognosis"),
118	        ("synopses", "synopsis"),
119	        ("theses", "thesis"),
120	    ] {
121	        if ends(from) {
122	            return replace_suffix(word, from, to);
123	        }
124	    }
125	    if ends("news") {
126	        return word.to_string();
127	    }
128	    if ends("ss") {
129	        return strip_last(word, 1);
130	    }
131	    if word.as_bytes()[word.len() - 1] == b's' {
132	        return strip_last(word, 1);
133	    }
134	    word.to_string()
135	}

1	//! Byte-level ASCII case and separator transformations.
2	
3	/// Insert `_` before each ASCII uppercase byte (unless at byte index 0) and
4	/// lowercase it; preserve everything else.
5	pub fn underscore(s: &str) -> String {
6	    let mut out = Vec::with_capacity(s.len());
7	    for (i, &b) in s.as_bytes().iter().enumerate() {
8	        if b.is_ascii_uppercase() {
9	            if i != 0 {
10	                out.push(b'_');
11	            }
12	            out.push(b.to_ascii_lowercase());
13	        } else {
14	            out.push(b);
15	        }
16	    }
17	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
18	}
19	
20	/// Shared camelize core: remove underscores and ASCII-uppercase the byte
21	/// immediately after each underscore. A non-letter byte after an underscore
22	/// still consumes the pending capitalize.
23	fn camel(s: &str, upper_first: bool) -> String {
24	    let mut out = Vec::with_capacity(s.len());
25	    let mut cap = upper_first;
26	    for &b in s.as_bytes() {
27	        if b == b'_' {
28	            cap = true;
29	            continue;
30	        }
31	        if cap {
32	            out.push(b.to_ascii_uppercase());
33	            cap = false;
34	        } else {
35	            out.push(b);
36	        }
37	    }
38	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
39	}
40	
41	/// Lower-camelize: byte 0 keeps its case.
42	pub fn camelize(s: &str) -> String {
43	    camel(s, false)
44	}
45	
46	/// Upper-camelize the entire input (byte 0 is ASCII-uppercased).
47	pub fn classify(s: &str) -> String {
48	    camel(s, true)
49	}
50	
51	/// underscore(input), then append `s`.
52	pub fn tableize(s: &str) -> String {
53	    let mut out = underscore(s);
54	    out.push('s');
55	    out
56	}
57	
58	/// Replace underscores with spaces; ASCII-uppercase only the first byte;
59	/// preserve all other case. Does not strip `_id`.
60	pub fn humanize(s: &str) -> String {
61	    let mut out: Vec<u8> = s
62	        .bytes()
63	        .map(|b| if b == b'_' { b' ' } else { b })
64	        .collect();
65	    if let Some(first) = out.first_mut() {
66	        *first = first.to_ascii_uppercase();
67	    }
68	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
69	}
70	
71	/// Split on literal spaces only: uppercase the first byte of each segment,
72	/// lowercase all remaining bytes; spaces preserved exactly.
73	pub fn titleize(s: &str) -> String {
74	    let mut out = Vec::with_capacity(s.len());
75	    let mut start = true;
76	    for &b in s.as_bytes() {
77	        if b == b' ' {
78	            out.push(b);
79	            start = true;
80	        } else if start {
81	            out.push(b.to_ascii_uppercase());
82	            start = false;
83	        } else {
84	            out.push(b.to_ascii_lowercase());
85	        }
86	    }
87	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
88	}
89	
90	/// Underscores become hyphens; nothing else changes.
91	pub fn dasherize(s: &str) -> String {
92	    let out: Vec<u8> = s
93	        .bytes()
94	        .map(|b| if b == b'_' { b'-' } else { b })
95	        .collect();
96	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
97	}
98	
99	/// Spaces become hyphens one-for-one; ASCII alphanumerics are kept and
100	/// ASCII-uppercased lowercased; every other byte is deleted.
101	pub fn parameterize(s: &str) -> String {
102	    let mut out = Vec::with_capacity(s.len());
103	    for &b in s.as_bytes() {
104	        if b == b' ' {
105	            out.push(b'-');
106	        } else if b.is_ascii_alphanumeric() {
107	            out.push(b.to_ascii_lowercase());
108	        }
109	    }
110	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
111	}
112	
113	/// ASCII byte-wise upcase.
114	pub fn upcase(s: &str) -> String {
115	    let out: Vec<u8> = s.bytes().map(|b| b.to_ascii_uppercase()).collect();
116	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
117	}
118	
119	/// ASCII byte-wise downcase.
120	pub fn downcase(s: &str) -> String {
121	    let out: Vec<u8> = s.bytes().map(|b| b.to_ascii_lowercase()).collect();
122	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
123	}
124	
125	/// Lowercase all bytes, then uppercase the first byte only.
126	pub fn capitalize(s: &str) -> String {
127	    let mut out: Vec<u8> = s.bytes().map(|b| b.to_ascii_lowercase()).collect();
128	    if let Some(first) = out.first_mut() {
129	        *first = first.to_ascii_uppercase();
130	    }
131	    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
132	}
